// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    DEP_BANK c;
    LogFile log_;

    function setUp() public {
        c = new DEP_BANK();
        log_ = new LogFile();
        c.SetLogFile(address(log_));
        c.Initialized();
    }

    function testFuzz_property(uint256 amount, bool attackerSucceeds) public {
        vm.assume(amount <= VALUE_CAP);
        // Admissible domain: positive amount only; keep it wide.
        vm.assume(amount > 0);

        ReentrantHelper helper = new ReentrantHelper(address(c), amount, attackerSucceeds);
        address attacker = address(helper);

        vm.deal(address(this), 0);
        vm.deal(attacker, amount);

        // The attacker must satisfy MinSum and have enough balance to collect.
        vm.prank(attacker);
        c.Deposit{value: amount}();

        // Set MinSum so the attacker is eligible on both the outer and inner call.
        // MinSum is initially 0, so the attacker already satisfies balances >= MinSum.
        // But on the outer call the attacker has `amount` and collects `amount`,
        // which sets their balance to 0. On the re-entrant call during the callback,
        // the reference already has balance 0 and cannot collect again;
        // the mutant still has balance amount and can collect again, draining c.
        uint256 before = attacker.balance;

        vm.prank(attacker);
        c.Collect(amount);

        // The helper records whether it observed the old balance during the callback.
        assertTrue(!helper.observedOldBalance(), "callee observed pre-subtraction balance");
    }
}

contract ReentrantHelper {
    DEP_BANK private immutable target;
    uint256 private immutable collectAmount;
    bool private immutable shouldSucceed;
    bool private entered;
    bool private observedOld;

    constructor(address _target, uint256 _amount, bool _succeed) {
        target = DEP_BANK(payable(_target));
        collectAmount = _amount;
        shouldSucceed = _succeed;
    }

    function observedOldBalance() external view returns (bool) {
        return observedOld;
    }

    receive() external payable {
        // Record whether the target still shows the pre-call balance for this contract.
        if (!entered && shouldSucceed) {
            entered = true;
            // During the callback, the attacker's balance in c should already be reduced by collectAmount.
            // If it is not, the mutant has not yet subtracted.
            if (target.balances(address(this)) >= collectAmount) {
                observedOld = true;
            }
        }
    }
}
